CREATE TABLE begrippen AS SELECT * FROM (VALUES
  ('HRBP', 'HR business partner: vaste HR-contactpersoon van een afdeling', 'hr.dim_medewerker'),
  ('SKO',  'Sales kick-off: jaarlijkse startbijeenkomst van verkoop', 'agenda.events'),
  ('ARR',  'Jaarlijkse terugkerende omzet, zonder diensten', 'finance.fct_arr')
) AS t(begrip, betekenis, bron_tabel);

-- Wat een agent opvraagt voordat hij een vraag over 'ARR' beantwoordt:
SELECT begrip, betekenis, bron_tabel
FROM begrippen
WHERE begrip IN ('ARR', 'HRBP')
ORDER BY begrip;
